import sqlite3,pathlib,shutil,json,hashlib,sys,time
src,pois,out,receipt=map(pathlib.Path,sys.argv[1:]);assert not out.exists();t=time.monotonic();shutil.copyfile(src,out);db=sqlite3.connect(out);db.execute('PRAGMA journal_mode=OFF');data=sqlite3.connect(pois);kinds={}
for raw,members in data.execute('SELECT tags,members FROM restrictions'):
 tags=json.loads(raw);members=json.loads(members);f=[m[1] for m in members if m[0]=='w' and m[2]=='from'];to=[m[1] for m in members if m[0]=='w' and m[2]=='to'];via=[m[1] for m in members if m[0]=='n' and m[2]=='via'];kind=tags.get('restriction:motorcar',tags.get('restriction:motor_vehicle',tags.get('restriction','')))
 if len(f)==len(to)==len(via)==1:kinds[(via[0],f[0],to[0],int(kind.startswith('only_')))]=kind
rows=list(db.execute('SELECT rowid,via,fromway,toway,onlyturn FROM turns'));db.execute("ALTER TABLE turns ADD COLUMN kind TEXT NOT NULL DEFAULT ''");updates=[(kinds.get((v,f,t,o),'blocked_ambiguous' if t==-1 else ''),row) for row,v,f,t,o in rows];db.executemany('UPDATE turns SET kind=? WHERE rowid=?',updates);db.commit();db.execute('VACUUM');assert db.execute('PRAGMA integrity_check').fetchone()[0]=='ok';meta={'source':str(src),'source_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'change':'Retain restriction kinds so same-way no_u_turn forbids reversing rather than continuing; one conservative ambiguous approach remains excluded','kind_counts':list(db.execute('SELECT kind,count(*) FROM turns GROUP BY kind')),'same_way_no_u_turn':db.execute("SELECT count(*) FROM turns WHERE kind='no_u_turn' AND fromway=toway").fetchone()[0],'bytes':out.stat().st_size,'sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'seconds':time.monotonic()-t};db.close();receipt.write_text(json.dumps(meta,indent=2)+'\n');print(json.dumps(meta,indent=2))
